<?php defined( 'ABSPATH' ) || exit; ?><div id="services-menu" data-menu-dropdown="services" aria-hidden="true" class="dropdown-panel"><div class="site-wrap dropdown-panel__grid"><div class="rail"><?php foreach ( array( 'wordpress-design' => 'WordPress Design', 'custom-theme-development' => 'Custom Theme Development', 'woocommerce' => 'WooCommerce', 'website-redesign' => 'Website Redesign', 'integrations-automation' => 'Integrations & Automation', 'support' => 'Website Care & Support' ) as $key => $label ) : ?><button type="button" data-rail-item="<?php echo esc_attr( $key ); ?>" aria-pressed="<?php echo $key === 'wordpress-design' ? 'true' : 'false'; ?>"><?php echo esc_html( $label ); ?></button><?php endforeach; ?></div><div class="rail-content"><?php foreach ( array( 'wordpress-design' => 'Purposeful, editorial WordPress websites.', 'custom-theme-development' => 'Reusable themes built for maintainability.', 'woocommerce' => 'Commerce sites that stay clear and usable.', 'website-redesign' => 'Sharper structure for existing content.', 'integrations-automation' => 'Practical handoff between tools and forms.', 'support' => 'Care plans that keep sites healthy.' ) as $key => $desc ) : ?><section data-rail-content="<?php echo esc_attr( $key ); ?>" class="rail-section<?php echo 'wordpress-design' === $key ? ' is-active' : ''; ?>"><h3><?php echo esc_html( ucwords( str_replace( '-', ' ', $key ) ) ); ?></h3><p><?php echo esc_html( $desc ); ?></p></section><?php endforeach; ?></div></div></div>
